 static Rect Bounds(byte[] p,int color){int left=400,right=-1,top=220,bottom=-1;for(int y=0;y<220;++y)for(int x=0;x<400;++x){int at=(y*400+x)*4;if(p[at+3]<150)continue;bool hit=color==0?p[at+2]>200&&p[at+1]<60&&p[at]<60:color==1?p[at+1]>180&&p[at+2]<60&&p[at]<60:p[at]>200&&p[at+1]<60&&p[at+2]<60;if(hit){left=Math.Min(left,x);right=Math.Max(right,x);top=Math.Min(top,y);bottom=Math.Max(bottom,y);}}return right<0?Rect.Empty:new Rect(left,top,right-left+1,bottom-top+1);}
