   var prefix=new Run(scenario==1?"lead ":scenario==2?"prefix zero\nprefix one\nprefix two\nprefix three\nprefix four\nprefix five\nlead ":scenario==3?"a longer leading phrase with several words before the first floating anchor ":"");var host=new Paragraph(prefix){Margin=new Thickness(0)};host.Inlines.Add(Make(firstText,Brushes.Red));host.Inlines.Add(Make(secondText,Brushes.Lime));if(scenario==4)host.Inlines.Add(Make(thirdText,Brushes.Blue));host.Inlines.Add(body);var doc=new FlowDocument(host){FontFamily=new FontFamily("Segoe UI"),FontSize=18,FlowDirection=direction,PagePadding=new Thickness(10),ColumnWidth=double.PositiveInfinity};doc.IsOptimalParagraphEnabled=scenario==1;TextOptions.SetTextFormattingMode(doc,mode);
