    Console.WriteLine($"oversized-group {mode} {direction}, scenario={scenario} page={pages}: red={red}, green={green}, blue={blue}");var view=((IServiceProvider)page).GetService(viewType);var local=new List<(TextPointer Start,TextPointer End)>();foreach(object segment in (IEnumerable)viewType.GetProperty("TextSegments").GetValue(view)){var t=segment.GetType();var start=(TextPointer)t.GetProperty("Start",I).GetValue(segment);var end=(TextPointer)t.GetProperty("End",I).GetValue(segment);ranges.Add((pages,start,end));local.Add((start,end));}foreach(var run in new[]{prefix,body})for(int at=0;at<Math.Min(30,run.Text.Length);++at){var position=run.ContentStart.GetPositionAtOffset(at,LogicalDirection.Forward);if(!local.Any(r=>position.CompareTo(r.Start)>=0&&position.CompareTo(r.End)<0))continue;var caret=(Rect)viewType.GetMethod("GetRectangleFromTextPosition").Invoke(view,new object[]{position});if(caret.IsEmpty||caret.Height<=0)throw new Exception("forced-prefix caret missing");if(viewType.GetMethod("GetTextPositionFromPoint").Invoke(view,new object[]{new Point(caret.Left+1,caret.Top+caret.Height/2),true})==null)throw new Exception("forced-prefix point mapping");}GC.Collect(2,GCCollectionMode.Forced,true,true);if(!pixels.SequenceEqual(Raster(page.Visual)))throw new Exception("oversized-group raster GC");
