   using(var page=paginator.GetPage(redPage))if(Bounds(Raster(page.Visual),0).IsEmpty)throw new Exception("oversized-group first page regeneration");using(var page=paginator.GetPage(greenPage))if(Bounds(Raster(page.Visual),1).IsEmpty)throw new Exception("oversized-group second page regeneration");if(scenario==4){using var third=paginator.GetPage(bluePage);if(Bounds(Raster(third.Visual),2).IsEmpty)throw new Exception("third object page regeneration");}Console.WriteLine($"original oversized-group {mode} {direction}, scenario={scenario}: {pages} pages, distinct object/source ownership and regeneration/GC PASS");
  }Dispatcher.CurrentDispatcher.InvokeShutdown();Console.WriteLine("original oversized floating-group progress and cleanup PASS");
